const item = $input.first().json;
const body = item.body || item;
const headers = item.headers || {};
const authHeader = headers.authorization || '';

const rawDate = (body.leaveDate || body.leave_date || '').trim();
const fmt = (d) => {
  if (!d) return '';
  const pd = new Date(d);
  if (isNaN(pd)) return d;
  return pd.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

return [{ json: {
  token: authHeader.replace('Bearer ', ''),
  leaveId: body.leaveId || '',
  reason: body.reason || 'Huy boi nhan vien',
  employeeName: body.employeeName || body.employee_name || '',
  employeeEmail: body.employeeEmail || body.employee_email || '',
  leaveDate: rawDate,
  leaveDateDisplay: fmt(rawDate),
  leaveDays: parseInt(body.leaveDays || body.leave_days || 0),
  department: body.department || '',
  managerEmail: body.managerEmail || '',
  hrEmail: body.hrEmail || '',
  frontendUrl: 'https://approvehub.internalautomation.io.vn' 
} }];

const input = $('Parse Input').first().json;
// Backend already cancelled the leave. wf6 only sends notification emails.
const needsHrNotify = input.hrEmail && input.hrEmail !== '';

return [{ json: {
  ...input,
  needsHrNotify,
  hrApprovalLink: needsHrNotify
    ? `${input.frontendUrl}/approval-page.html?token=${encodeURIComponent(input.hrApprovalToken || '')}&hr=true`
    : ''
} }];

